import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";import"./chunks/assets.ByxXdwmG.js";var i=JSON.parse(`{"title":"Site settings and shared design","description":"","frontmatter":{},"headers":[],"relativePath":"en/guides/sites.md","filePath":"en/guides/sites.md","lastUpdated":1794405696000}`),a={name:`en/guides/sites.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="site-settings-and-shared-design" tabindex="-1">Site settings and shared design <a class="header-anchor" href="#site-settings-and-shared-design" aria-label="Permalink to “Site settings and shared design”">​</a></h1><p>Select the target site in the header and open &quot;Site settings (「サイト設定」)&quot;. Site admins and superusers can change them. Adding a new site is done by a superuser in &quot;JevSense management (「JevSense管理」)&quot;.</p><h2 id="basic-settings" tabindex="-1">Basic settings <a class="header-anchor" href="#basic-settings" aria-label="Permalink to “Basic settings”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Example and meaning</th></tr></thead><tbody><tr><td>Site name</td><td>The name used in the admin console. Can be changed later</td></tr><tr><td>Site ID</td><td>Matches <code>data-site</code> in the SDK. Can&#39;t be changed after creation</td></tr><tr><td>Allowed origins</td><td><code>https://example.com</code>. No path and no trailing slash</td></tr><tr><td>Paths to collect</td><td><code>/ja/</code>. Prefix match, one per line</td></tr><tr><td>Paths not to collect</td><td><code>/ja/account</code>, <code>/ja/checkout</code>, <code>/ja/search</code> and so on</td></tr><tr><td>Metadata sending</td><td>Enable it after you&#39;ve checked the information on the target pages</td></tr><tr><td>Display time for a valid view</td><td>In milliseconds. The threshold for excluding very short views from the evidence</td></tr><tr><td>Valid views required</td><td>The number of valid page views needed before judging starts</td></tr></tbody></table><p>A newly created site has sending and campaigns disabled. Check the settings and choose &quot;Save settings (「設定を保存」)&quot;. After you change what is collected, reload the target pages so the SDK picks up the new settings.</p><h3 id="origin-versus-path" tabindex="-1">Origin versus path <a class="header-anchor" href="#origin-versus-path" aria-label="Permalink to “Origin versus path”">​</a></h3><p>An example for targeting <code>https://adobe.customer-experience.dev/ja/</code>.</p><ul><li>Origin: <code>https://adobe.customer-experience.dev</code></li><li>Path to collect: <code>/ja/</code></li><li>Page to display on: on the campaign side, for example an exact match of <code>/ja/</code></li></ul><p>What you collect and where you display are separate. You can collect product pages as evidence and show the message only on the home page.</p><h2 id="additional-events-and-states" tabindex="-1">Additional events and states <a class="header-anchor" href="#additional-events-and-states" aria-label="Permalink to “Additional events and states”">​</a></h2><p>Register event names and state names only when you integrate your own clicks, applications, bookings, carts and similar. The SDK accepts only registered names. See <a href="./../integration/sdk#optional-events-and-states">optional integrations</a>.</p><h2 id="the-site-s-shared-basic-design" tabindex="-1">The site&#39;s shared basic design <a class="header-anchor" href="#the-site-s-shared-basic-design" aria-label="Permalink to “The site&#39;s shared basic design”">​</a></h2><p>&quot;Shared design (「共通デザイン」)&quot; sets the look applied to all standard campaigns of that site.</p><table tabindex="0"><thead><tr><th>Target</th><th>What you can adjust</th></tr></thead><tbody><tr><td>Common</td><td>Background, text and button colors, font, font size, corner radius, spacing</td></tr><tr><td>Modal</td><td>Width, darkness of the backdrop</td></tr><tr><td>Floating</td><td>Width, bottom right or bottom left, margin from the screen edge</td></tr><tr><td>Notification bar</td><td>Top or bottom</td></tr></tbody></table><p><img src="/jev-personalization/images/design.png" alt="Shared design" width="1440" height="1892"></p><p>You can switch the display type in the preview on the right while you check. Changes you are typing don&#39;t reach the site until you save. Saving also applies to campaigns that are already being delivered.</p><h2 id="allowing-custom-javascript" tabindex="-1">Allowing custom JavaScript <a class="header-anchor" href="#allowing-custom-javascript" aria-label="Permalink to “Allowing custom JavaScript”">​</a></h2><p>This is allowed per site. Only site admins or superusers can create, change and preview code. Code runs with the same privileges as your site, so register only code you trust. Also read <a href="./presentation">display types and custom code</a>.</p><h2 id="jev-connection-per-site" tabindex="-1">Jev connection per site <a class="header-anchor" href="#jev-connection-per-site" aria-label="Permalink to “Jev connection per site”">​</a></h2><p>Set the site-only API key and the usage stop in <a href="./jev">Jev connection (「Jev連携」)</a> in the left menu. You don&#39;t need to write the key into the site settings JSON or the SDK tag. Only site admins and superusers can operate it and view usage records.</p><h2 id="fetching-page-information-and-checking-on-a-real-page" tabindex="-1">Fetching page information and checking on a real page <a class="header-anchor" href="#fetching-page-information-and-checking-on-a-real-page" aria-label="Permalink to “Fetching page information and checking on a real page”">​</a></h2><p>The &quot;Page information fetching (「ページ情報の取得」)&quot; tab sets how this site fetches information in common. Site admins and superusers can change it.</p><ol><li>Choose <strong>standard automatic fetching</strong> or <strong>site-specific rules</strong>. Standard takes the page name in the order OGP → title, and the description in the order OGP → meta description. Choose custom if you use JSON-LD.</li><li>With custom, arrange candidates from the top. Use &quot;Edit&quot; to set the conditions, the source and key for the page name and description, a prefix, and how to handle a missing description. Conditions are evaluated against the same JSON-LD object.</li><li>In <strong>Page URL to check</strong> on the right, enter a URL within the registered site and the paths to collect, and press <strong>Check with this URL</strong>.</li><li>On the real page in the other tab, complete the measurement consent if needed. The admin console then shows the page name, description, the candidate used and the reasons for rejected ones. You can check even an unsaved draft of the settings.</li><li>If everything looks right, press <strong>Review changes → Save</strong>.</li></ol><p>A check is valid for 5 minutes. It needs the latest SDK and metadata sending enabled in the basic settings. Normal Jev judgment, offer display and saving browsing history are not performed. The permission for checking is limited to this admin session, site and URL, and the connection can be started only once.</p><p>If the meta information changes on the page, the result updates too. <strong>Fetch again from the same page</strong> also rechecks. When you change the draft settings, the old result is cleared and the checking connection is ended. To check with the changed content, press <strong>Check with this URL</strong> again.</p><p>If it can&#39;t connect, check the tag placement and update, completion of consent, CSP, allowing pop-ups and Cross-Origin-Opener-Policy. On a site where COOP cuts the connection with the other tab, this way of checking isn&#39;t available. Before introducing the SDK, or when it can&#39;t connect, you can try only the rules with the collapsed artificial data input. It is shown separately from real-page measurement.</p><p>For an existing site with no fetching settings, the previous JSON-LD-first behavior continues until you switch and save. After saving, it applies the next time the SDK fetches its settings. Browsing history from before the change is discarded, and the displayed state is kept. For the fetched keys and their priority, see <a href="./../integration/data">data collected and sent</a>.</p><h2 id="keys-excluded-from-url-collection" tabindex="-1">Keys excluded from URL collection <a class="header-anchor" href="#keys-excluded-from-url-collection" aria-label="Permalink to “Keys excluded from URL collection”">​</a></h2><p>At the top of &quot;Page information fetching&quot;, enter the <strong>GET parameter keys not to collect</strong>, one per line. For example, if you specify <code>email</code> and <code>token</code>, those keys and values are removed from the URLs of the current page, the entry page and the valid view history. GET parameters you don&#39;t specify are kept.</p><p>If you enter a URL to check on the right, you can see the URL that would be saved and sent right there. This display alone doesn&#39;t communicate externally. The exclusion setting can be saved in standard, custom or legacy metadata mode. Once you save it from &quot;Review changes&quot;, it applies the next time the settings are loaded. It isn&#39;t reflected immediately in another tab that is still open.</p><p>Keys are case-sensitive and are matched exactly after URL decoding. If the same key appears several times, all of them are removed. The limit is 50 keys of up to 100 characters each. For details, see <a href="./../integration/data#page-url-and-excluded-keys">data collected and sent</a>.</p>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};